"""Measure the full owned process tree over an actual native renderer pause."""
import json,subprocess,sys,time
from desktop_visual import *
click('Chat');click('New conversation');wait('!document.querySelector(".viewer-banner")');text('textarea[aria-label="Message AG1"]','[stream] Background work continues across a renderer pause');wait('![...document.querySelectorAll("button")].find(b=>b.getAttribute("aria-label")==="Send message").disabled');click('Send message');wait('[...document.querySelectorAll("button")].some(b=>b.getAttribute("aria-label")==="Stop generation")')
metrics=subprocess.Popen([sys.executable,str(ROOT/'tools/probes/desktop_metrics.py'),'ag1','--seconds','8','--label','paused-renderer'],stdout=subprocess.PIPE,text=True)
assert 'Measuring' in metrics.stdout.readline();start=time.monotonic();js('(()=>{const until=performance.now()+3000;while(performance.now()<until){}return true;})()');end=time.monotonic();wait('document.querySelector("footer").innerText.includes("All caught up")');snapshot=async_js('return (await window.__TAURI_INTERNALS__.invoke("bridge_view")).snapshot');assert snapshot['status']=='idle';assert metrics.wait(timeout=15)==0
measurement=json.loads((ROOT/'implementation/evidence/P04/ag1-paused-renderer-metrics.json').read_text());assert measurement['samples'][0]['time']<=start<end<=measurement['samples'][-1]['time']
(ROOT/'implementation/evidence/P04/native-paused-renderer.json').write_text(json.dumps({'renderer_busy_ms':3000,'start_monotonic':start,'end_monotonic':end,'worker_completed':True,'snapshot':snapshot,'no_live_model':True,'measurement_covers_pause':True},indent=2));click('New conversation');wait('document.body.innerText.includes("Ready when you are.")');print('Measured renderer pause while the owned SDK worker completed; fresh conversation restored.')
